@startuml

class Organizer {
  + firstName : string
  + lastName : string
  + email : string
  + postalAddress : string
  + phoneNumber : string
  + password : string
}

class EventType {
  + name : string
}

class Location {
  + name : string
  + address : string
}

class Event {
  + occasion : string
  + startDateTime : datetime
  + endDateTime : datetime
}

class Attendee {
  + firstName : string
  + lastName : string
  + email : string
  + password : string
  + attendanceStatus : string
}

class Task {
  + description : string
  + status : string
}

class TaskAssignment {
}

Attendee "0..*" -- "0..*" Task : selects
Task "0..*" -- "0..*" Attendee : is assigned to
Task "1" -- "0..*" TaskAssignment : recorded in

Organizer "1..*" -- "0..*" Event : organizes
Organizer "0..1" -- "0..*" Event : attends
Event "1" -- "0..*" Task : has
Event "1" -- "1" EventType : is of type
Event "1" -- "1" Location : is at
Event "1" -- "0..*" Attendee : invites

Organizer "0..*" -- "0..*" EventType : creates
Organizer "0..*" -- "0..*" Location : creates

@enduml

